package dev.pocketengine.store;
import android.app.Application;
import dev.pocketengine.core.RunControl;
import java.util.UUID;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
public final class OwnerInputMailboxTest {
 static final class Fixture {final TaskStore store=new TaskStore(RuntimeEnvironment.getApplication());final String conversation=UUID.randomUUID().toString(),id,run;final int epoch;final RunControl control=new RunControl();Fixture()throws Exception{JSONObject t=store.startAttempt(store.createCapabilityTask("original owner goal",conversation).getString("id"),"capabilities",12);id=t.getString("id");run=t.getString("runId");epoch=t.getInt("coordinatorEpoch");control.bindHostRun(id,run,epoch);store.openOwnerInputMailbox(id,run,epoch,conversation,control);}JSONObject append(JSONObject message,String mode)throws Exception{return store.appendOwnerInput(id,run,epoch,conversation,message,mode,control);}JSONArray poll(JSONArray included,boolean boundary,boolean close)throws Exception{return store.pollOwnerInputs(id,run,epoch,included,boundary,close,control);}}
 static JSONObject message(String text)throws Exception{return new JSONObject().put("id",UUID.randomUUID().toString()).put("clientMessageId",UUID.randomUUID().toString()).put("content",text).put("attachments",new JSONArray());}
 @Test public void originalTaskKeepsInputsAndSemanticClientDedupWithoutNewRunOrEffect()throws Exception{Fixture f=new Fixture();JSONObject first=message("queue original owner input");JSONObject accepted=f.append(first,"queue");JSONObject retry=new JSONObject(first.toString()).put("id",UUID.randomUUID().toString()).put("at",123);assertTrue(f.append(retry,"queue").getBoolean("duplicate"));assertEquals(accepted.getString("messageId"),f.append(retry,"queue").getString("messageId"));assertThrows(SecurityException.class,()->f.append(new JSONObject(first.toString()).put("content","changed input"),"queue"));JSONObject task=f.store.get(f.id,false);assertEquals(f.run,task.getString("runId"));assertEquals(f.epoch,task.getInt("coordinatorEpoch"));assertEquals(1,task.getJSONArray("ownerInputs").length());assertEquals(0,task.getJSONArray("operations").length());assertEquals(1,f.store.list().length());}
 @Test public void queueWaitsForTurnBoundarySteerArrivesEarlierAndPollDoesNotConsumeBeforeCheckpoint()throws Exception{Fixture f=new Fixture();JSONObject queue=message("later follow-up"),steer=message("next safe model step");f.append(queue,"queue");f.append(steer,"steer");JSONArray early=f.poll(new JSONArray(),false,true);assertEquals(1,early.length());assertEquals(steer.getString("id"),early.getJSONObject(0).getString("messageId"));assertEquals(1,f.poll(new JSONArray(),false,false).length());assertEquals(2,f.poll(new JSONArray(),true,false).length());assertTrue(f.store.get(f.id,false).getJSONObject("ownerInputMailbox").getBoolean("open"));assertEquals(0,f.poll(new JSONArray().put(queue.getString("id")).put(steer.getString("id")),true,true).length());assertFalse(f.store.get(f.id,false).getJSONObject("ownerInputMailbox").getBoolean("open"));assertThrows(IllegalStateException.class,()->f.append(message("too late"),"queue"));}
 @Test public void closedMailboxCannotBeReopenedBySameRunAndLateAppendLosesNoAcceptedRow()throws Exception{Fixture f=new Fixture();JSONObject row=message("accepted before close");f.append(row,"queue");f.poll(new JSONArray().put(row.getString("id")),true,true);assertFalse(f.store.openOwnerInputMailbox(f.id,f.run,f.epoch,f.conversation,f.control).getBoolean("open"));assertThrows(IllegalStateException.class,()->f.append(message("new input after close"),"steer"));assertEquals(1,f.store.get(f.id,false).getJSONArray("ownerInputs").length());}
 @Test public void pauseCancelForeignConversationOldEpochAndPreparedUnknownCannotAdmitNewInput()throws Exception{Fixture f=new Fixture();JSONObject m=message("safe input");f.control.pause();assertEquals(m.getString("id"),f.append(m,"queue").getString("messageId"));assertThrows(IllegalStateException.class,()->f.poll(new JSONArray(),true,false));f.control.resume();assertThrows(SecurityException.class,()->f.store.appendOwnerInput(f.id,f.run,f.epoch,"other-conversation",m,"queue",f.control));assertThrows(SecurityException.class,()->f.store.appendOwnerInput(f.id,f.run,f.epoch+1,f.conversation,m,"queue",f.control));f.store.authorizeTools(f.id,f.run,new JSONArray().put("workspace_write"));String operation=f.store.journal(f.id,f.run,f.epoch,f.control).beginOperation("workspace_write",new JSONObject());assertEquals(m.getString("id"),f.append(m,"queue").getString("messageId"));assertThrows(IllegalStateException.class,()->f.poll(new JSONArray(),true,false));f.store.journal(f.id,f.run,f.epoch,f.control).finishOperation(operation,new JSONObject().put("status","unknown"));assertThrows(IllegalStateException.class,()->f.append(m,"queue"));f.control.cancel();assertThrows(Exception.class,()->f.poll(new JSONArray(),true,false));}
 @Test public void referencesAreImmutableMetadataOnlyAndRejectPayloadChanges()throws Exception{Fixture f=new Fixture();JSONObject m=message("look at selected image");JSONObject ref=new JSONObject().put("id",UUID.randomUUID().toString()).put("sha256","a".repeat(64)).put("mimeType","image/png").put("size",71);m.getJSONArray("attachments").put(ref);JSONObject accepted=f.append(m,"queue");assertEquals("a".repeat(64),accepted.getJSONArray("attachments").getJSONObject(0).getString("sha256"));ref.put("sha256","b".repeat(64));assertThrows(SecurityException.class,()->f.append(m,"queue"));String encoded=f.store.get(f.id,false).getJSONArray("ownerInputs").toString();assertFalse(encoded.contains("image_url"));assertFalse(encoded.contains("base64"));}
 @Test public void explicitNewAttemptAfterRestartRestoresUnconsumedOriginalRowsButCannotAutoReuseOldGrant()throws Exception{Fixture f=new Fixture();JSONObject m=message("accepted owner request survives");f.append(m,"queue");TaskStore reopened=new TaskStore(RuntimeEnvironment.getApplication());assertThrows(SecurityException.class,()->reopened.pollOwnerInputs(f.id,f.run,f.epoch,new JSONArray(),true,false,f.control));JSONObject attempt=reopened.startAttempt(f.id,"capabilities",8);RunControl resumed=new RunControl();resumed.bindHostRun(f.id,attempt.getString("runId"),attempt.getInt("coordinatorEpoch"));reopened.openOwnerInputMailbox(f.id,attempt.getString("runId"),attempt.getInt("coordinatorEpoch"),f.conversation,resumed);JSONArray rows=reopened.pollOwnerInputs(f.id,attempt.getString("runId"),attempt.getInt("coordinatorEpoch"),new JSONArray(),true,false,resumed);assertEquals(m.getString("id"),rows.getJSONObject(0).getString("messageId"));assertEquals(1,reopened.list().length());assertEquals(0,reopened.get(f.id,false).getJSONArray("operations").length());}
 @Test public void unresolvedConversationLookupUsesWholeDatabaseAndEndAttemptClosesMailbox()throws Exception{Fixture f=new Fixture();f.store.authorizeTools(f.id,f.run,new JSONArray().put("workspace_write"));f.store.journal(f.id,f.run,f.epoch,f.control).beginOperation("workspace_write",new JSONObject());for(int i=0;i<205;i++)f.store.create("later "+i);assertEquals(f.id,f.store.ownerConversationUnresolved(f.conversation).getString("id"));f.store.endAttempt(f.id,f.run,"cancelled","stop",new JSONObject());assertFalse(f.store.get(f.id,false).getJSONObject("ownerInputMailbox").getBoolean("open"));assertTrue(f.store.hasUnresolved(f.id));}
 @Test public void sixtyFifthInputIsRefusedBeforeAcknowledgementOrRuntimeOversize(){try{Fixture f=new Fixture();for(int i=0;i<64;i++)f.append(message("input "+i),"queue");assertEquals(64,f.poll(new JSONArray(),true,false).length());assertThrows(IllegalStateException.class,()->f.append(message("not admitted"),"queue"));assertEquals(64,f.store.get(f.id,false).getJSONArray("ownerInputs").length());}catch(Exception failure){throw new AssertionError(failure);}}

}
